class Solution:
    def minKBitFlips(self, nums: List[int], k: int) -> int:
        flips = [0]*len(nums)
        csum = 0

        for left in range(0, len(nums)-k+1):
            if (nums[left] + csum) % 2 == 0:
                flips[left] += 1
                csum += 1
            if left >= k-1:
                csum -= flips[left-k+1]

        for check in range(len(nums)-k+1, len(nums)):
            if (nums[check] + csum) % 2 == 0:
                return -1
            if check >= k-1:
                csum -= flips[check-k+1]

        return sum(flips)

class Solution:
    def minKBitFlips(self, A, K):
        result, curr = 0, 0
        for i in range(len(A)):
            if i >= K:
                curr -= A[i-K]//2
            if curr & 1 ^ A[i] == 0:
                if i+K > len(A):
                    return -1
                A[i] += 2
                curr, result = curr+1, result+1
        return result

